-- V1.2: the stalled-lead monitor is an operational control, not a generic
-- app-settings writer. The existing row is provisioned by the forward
-- Production contract; this RPC is the only runtime write authority for it.

begin;

create or replace function public.set_v12_adaptive_stalled_lead_controls(
  p_enabled boolean,
  p_inactivity_hours integer,
  p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_setting_key constant text := 'v12_adaptive_stalled_lead_controls';
  v_source constant text := 'v12_forward_contract';
  v_reason text := pg_catalog.btrim(coalesce(p_reason, ''));
  v_current jsonb;
  v_next jsonb;
  v_previous_enabled boolean;
  v_previous_hours integer;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_enabled is null then
    raise exception 'v12_stalled_lead_controls:enabled_required';
  end if;

  if p_inactivity_hours is null
     or p_inactivity_hours < 1
     or p_inactivity_hours > 168 then
    raise exception 'v12_stalled_lead_controls:inactivity_hours_out_of_range';
  end if;

  if pg_catalog.char_length(v_reason) < 10
     or pg_catalog.char_length(v_reason) > 500 then
    raise exception 'v12_stalled_lead_controls:meaningful_reason_required';
  end if;

  select s.value_json
    into v_current
    from public.app_settings as s
   where s.setting_key = v_setting_key
   for update;

  if not found then
    raise exception 'v12_stalled_lead_controls:setting_missing';
  end if;

  if pg_catalog.jsonb_typeof(v_current) <> 'object'
     or (select count(*) from pg_catalog.jsonb_object_keys(v_current)) <> 3
     or not (v_current ? 'source')
     or not (v_current ? 'enabled')
     or not (v_current ? 'inactivity_hours')
     or v_current->>'source' is distinct from v_source
     or pg_catalog.jsonb_typeof(v_current->'enabled') <> 'boolean'
     or pg_catalog.jsonb_typeof(v_current->'inactivity_hours') <> 'number'
     or v_current->>'inactivity_hours' !~ '^[0-9]{1,3}$' then
    raise exception 'v12_stalled_lead_controls:unexpected_current_shape';
  end if;

  v_previous_enabled := (v_current->>'enabled')::boolean;
  v_previous_hours := (v_current->>'inactivity_hours')::integer;
  if v_previous_hours < 1 or v_previous_hours > 168 then
    raise exception 'v12_stalled_lead_controls:unexpected_current_shape';
  end if;

  v_next := pg_catalog.jsonb_build_object(
    'source', v_source,
    'enabled', p_enabled,
    'inactivity_hours', p_inactivity_hours
  );

  perform pg_catalog.set_config('phase14.authoritative_transition', 'policy_approval', true);

  update public.app_settings
     set value_json = v_next,
         updated_at = v_now
   where setting_key = v_setting_key;

  if not found then
    raise exception 'v12_stalled_lead_controls:update_failed';
  end if;

  insert into public.audit_logs(
    actor_type,
    entity_table,
    action,
    before_json,
    after_json
  ) values (
    'system',
    'app_settings',
    'v12_stalled_lead_controls_changed',
    pg_catalog.jsonb_build_object(
      'setting_key', v_setting_key,
      'source', v_source,
      'enabled', v_previous_enabled,
      'inactivity_hours', v_previous_hours
    ),
    pg_catalog.jsonb_build_object(
      'setting_key', v_setting_key,
      'source', v_source,
      'enabled', p_enabled,
      'inactivity_hours', p_inactivity_hours,
      'reason', v_reason
    )
  );

  return pg_catalog.jsonb_build_object(
    'setting_key', v_setting_key,
    'value_json', v_next,
    'changed_at', v_now,
    'audit_action', 'v12_stalled_lead_controls_changed'
  );
end;
$$;

revoke all on function public.set_v12_adaptive_stalled_lead_controls(boolean, integer, text)
  from public, anon, authenticated, service_role;
grant execute on function public.set_v12_adaptive_stalled_lead_controls(boolean, integer, text)
  to service_role;

comment on function public.set_v12_adaptive_stalled_lead_controls(boolean, integer, text) is
  'Audited service-role-only setter for the fixed v12_adaptive_stalled_lead_controls app setting. Validates the v12_forward_contract shape, preserves direct table-write lockdown, updates atomically and records the previous/new control state without customer data.';

commit;

-- V1.2: Supabase Cron is the sole scheduler for the stalled-lead monitor.
-- The bearer value is resolved from Vault when the job runs; it is never stored in this
-- migration or in cron.job.command.

begin;

create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net;

revoke all on schema cron from public, anon, authenticated;
revoke all on schema net from public, anon, authenticated;
do $$
declare
  v_function regprocedure;
begin
  for v_function in
    select p.oid::regprocedure
      from pg_catalog.pg_proc as p
      join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
     where n.nspname in ('cron', 'net')
  loop
    execute pg_catalog.format(
      'revoke all on function %s from public, anon, authenticated',
      v_function
    );
  end loop;
end;
$$;

do $$
declare
  v_job_count integer;
  v_job_id bigint;
  v_command text := $cron_command$
select net.http_get(
  url := 'https://www.mkfraud.co.za/score/api/internal/adaptive-stalled-leads',
  headers := jsonb_build_object(
    'Authorization', 'Bearer ' || (
      select decrypted_secret
      from vault.decrypted_secrets
      where name = 'v12_stalled_lead_cron_secret'
      limit 1
    )
  ),
  timeout_milliseconds := 60000
);
$cron_command$;
  v_secret_count integer;
  v_valid_secret_count integer;
begin
  if pg_catalog.to_regclass('vault.decrypted_secrets') is null then
    raise exception 'v12_stalled_lead_scheduler:vault_unavailable';
  end if;

  select count(*)::integer
    into v_secret_count
    from vault.decrypted_secrets
   where name = 'v12_stalled_lead_cron_secret';
  select count(*)::integer
    into v_valid_secret_count
    from vault.decrypted_secrets
   where name = 'v12_stalled_lead_cron_secret'
     and pg_catalog.char_length(decrypted_secret) >= 43;
  if v_secret_count <> 1 or v_valid_secret_count <> 1 then
    raise exception 'v12_stalled_lead_scheduler:cron_secret_missing_or_ambiguous';
  end if;

  select count(*)::integer
    into v_job_count
    from cron.job
   where jobname = 'v12-stalled-lead-monitor';

  if v_job_count > 1 then
    raise exception 'v12_stalled_lead_scheduler:duplicate_job_name';
  elsif v_job_count = 1 then
    if not exists (
      select 1
        from cron.job
       where jobname = 'v12-stalled-lead-monitor'
         and schedule = '0 * * * *'
         and command = v_command
         and active is true
    ) then
      raise exception 'v12_stalled_lead_scheduler:existing_job_contract_mismatch';
    end if;
    return;
  end if;

  select cron.schedule(
    'v12-stalled-lead-monitor',
    '0 * * * *',
    v_command
  ) into v_job_id;

  if not exists (
    select 1
      from cron.job
     where jobid = v_job_id
       and jobname = 'v12-stalled-lead-monitor'
       and schedule = '0 * * * *'
       and command = v_command
       and active is true
  ) then
    raise exception 'v12_stalled_lead_scheduler:job_contract_not_created';
  end if;
end;
$$;

commit;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.assessments'::regclass
      and conname = 'assessments_monitoring_run_id_chk'
  ) then
    alter table public.assessments
      add constraint assessments_monitoring_run_id_chk
      check (monitoring_run_id is null or monitoring_run_id ~ '^[A-Za-z0-9._:-]{1,100}$');
  end if;
end $$

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.phase14_operational_alerts'::regclass
      and conname = 'phase14_operational_alerts_monitoring_priority_chk'
  ) then
    alter table public.phase14_operational_alerts
      add constraint phase14_operational_alerts_monitoring_priority_chk
      check (monitoring_priority is null or monitoring_priority in ('P1','P2','P3'));
  end if;
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.phase14_operational_alerts'::regclass
      and conname = 'phase14_operational_alerts_deployment_sha_chk'
  ) then
    alter table public.phase14_operational_alerts
      add constraint phase14_operational_alerts_deployment_sha_chk
      check (deployment_sha is null or deployment_sha ~ '^[0-9a-f]{40}$');
  end if;
end $$

-- Environment-isolate adaptive customer_start activation.
--
-- Root cause closed by this migration:
-- Preview and Production previously shared a single row keyed only by policy_key. Any Preview
-- certification call to set_adaptive_activation('preview', ...) rewrote the Production binding
-- and immediately caused Production adaptive activation and signed readiness to fail.
--
-- The policy identity is now (policy_key, environment). Preview and Production can be rebound
-- independently without mutating each other's release authority.

begin;

alter table public.adaptive_activation_policies
  drop constraint if exists adaptive_activation_policies_pkey;

alter table public.adaptive_activation_policies
  add constraint adaptive_activation_policies_pkey
  primary key (policy_key, environment);

-- Historical replay may arrive with only Preview; live Production may arrive with only Production.
-- Seed the missing counterpart disabled. Operator activation remains explicit and audited.
insert into public.adaptive_activation_policies(
  policy_key, environment, supabase_project, graph_version, graph_fingerprint,
  enabled, activation_sha, activated_at, activated_by, reason, created_at, updated_at
)
select
  policy_key,
  'preview',
  supabase_project,
  graph_version,
  graph_fingerprint,
  false,
  null,
  null,
  null,
  'Environment-isolated Preview policy created disabled; explicit Preview activation required.',
  now(),
  now()
from public.adaptive_activation_policies
where policy_key = 'customer_start'
  and environment = 'production'
on conflict (policy_key, environment) do nothing;

insert into public.adaptive_activation_policies(
  policy_key, environment, supabase_project, graph_version, graph_fingerprint,
  enabled, activation_sha, activated_at, activated_by, reason, created_at, updated_at
)
select
  policy_key,
  'production',
  supabase_project,
  graph_version,
  graph_fingerprint,
  false,
  null,
  null,
  null,
  'Environment-isolated Production policy created disabled; explicit Production activation required.',
  now(),
  now()
from public.adaptive_activation_policies
where policy_key = 'customer_start'
  and environment = 'preview'
on conflict (policy_key, environment) do nothing;

do $$
begin
  if (select count(*) from public.adaptive_activation_policies where policy_key = 'customer_start') <> 2
     or not exists (
       select 1 from public.adaptive_activation_policies
       where policy_key = 'customer_start' and environment = 'preview'
     )
     or not exists (
       select 1 from public.adaptive_activation_policies
       where policy_key = 'customer_start' and environment = 'production'
     ) then
    raise exception 'adaptive_activation_environment_isolation_seed_failed';
  end if;
end;
$$;

create or replace function public.set_adaptive_activation(
  p_environment text,
  p_supabase_project text,
  p_enabled boolean,
  p_head_sha text,
  p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_environment text := lower(trim(coalesce(p_environment, '')));
  v_project text := lower(trim(coalesce(p_supabase_project, '')));
  v_head_sha text := lower(trim(coalesce(p_head_sha, '')));
  v_reason text := trim(coalesce(p_reason, ''));
  v_policy public.adaptive_activation_policies%rowtype;
  v_graph public.adaptive_graph_versions%rowtype;
begin
  if v_environment not in ('preview', 'production') then
    raise exception 'adaptive_activation_environment_invalid';
  end if;
  if v_project !~ '^[a-z0-9]{20}$' then
    raise exception 'adaptive_activation_project_invalid';
  end if;
  if v_head_sha !~ '^[0-9a-f]{40}$' then
    raise exception 'adaptive_activation_sha_invalid';
  end if;
  if v_reason = '' then
    raise exception 'adaptive_activation_reason_required';
  end if;
  if p_enabled is null then
    raise exception 'adaptive_activation_enabled_required';
  end if;

  select * into v_policy
  from public.adaptive_activation_policies
  where policy_key = 'customer_start'
    and environment = v_environment
  for update;
  if not found then
    raise exception 'adaptive_activation_policy_missing';
  end if;

  if not (
    (v_policy.graph_version = 'MFRS-V1.1-ADAPTIVE-DRAFT-20260804'
      and v_policy.graph_fingerprint = 'fa4505253f7e85a76f37e87e0836db76c553a786a4030fe29298153fc3b8f7ab')
    or
    (v_policy.graph_version = 'MFRS-V1.2-ADAPTIVE-CANDIDATE-20260821'
      and v_policy.graph_fingerprint = '6f1f098a713b1a2f2bf6fc52a1733bf4ffafea8adccedaccc0b721e55bbe45c7')
  ) then
    raise exception 'adaptive_activation_graph_binding_invalid';
  end if;

  select * into v_graph
  from public.adaptive_graph_versions
  where graph_version = v_policy.graph_version
    and graph_fingerprint = v_policy.graph_fingerprint;
  if not found or v_graph.status <> 'published' then
    raise exception 'adaptive_graph_must_be_published';
  end if;
  if v_graph.compiled_graph_json->>'graphVersion' is distinct from v_graph.graph_version
     or v_graph.compiled_graph_json->>'methodologyVersion' is distinct from v_graph.methodology_version
     or v_graph.compiled_graph_json->>'graphFingerprint' is distinct from v_graph.graph_fingerprint then
    raise exception 'adaptive_graph_identity_mismatch';
  end if;

  update public.adaptive_activation_policies
  set supabase_project = v_project,
      enabled = p_enabled,
      activation_sha = case when p_enabled then v_head_sha else null end,
      activated_at = case when p_enabled then now() else null end,
      activated_by = case when p_enabled then 'rc2_service_role_control' else null end,
      reason = v_reason,
      updated_at = now()
  where policy_key = 'customer_start'
    and environment = v_environment
  returning * into v_policy;

  insert into public.audit_logs(actor_type, entity_table, action, after_json)
  values (
    'system',
    'adaptive_activation_policies',
    'adaptive_activation_changed',
    jsonb_build_object(
      'policy_key', v_policy.policy_key,
      'enabled', v_policy.enabled,
      'environment', v_policy.environment,
      'supabase_project', v_policy.supabase_project,
      'graph_version', v_policy.graph_version,
      'graph_fingerprint', v_policy.graph_fingerprint,
      'activation_sha', v_policy.activation_sha,
      'reason', v_policy.reason
    )
  );

  return to_jsonb(v_policy);
end;
$$;

revoke all on function public.set_adaptive_activation(text, text, boolean, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.set_adaptive_activation(text, text, boolean, text, text)
  to service_role;

create or replace function public.set_adaptive_staging_activation(
  p_enabled boolean,
  p_head_sha text,
  p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_graph public.adaptive_graph_versions%rowtype;
begin
  select * into v_graph
  from public.adaptive_graph_versions
  where graph_version = 'MFRS-V1.2-ADAPTIVE-CANDIDATE-20260821'
    and graph_fingerprint = '6f1f098a713b1a2f2bf6fc52a1733bf4ffafea8adccedaccc0b721e55bbe45c7';
  if not found or v_graph.status <> 'published' then
    raise exception 'adaptive_v12_graph_must_be_published';
  end if;

  update public.adaptive_activation_policies
  set graph_version = v_graph.graph_version,
      graph_fingerprint = v_graph.graph_fingerprint,
      updated_at = now()
  where policy_key = 'customer_start'
    and environment = 'preview';
  if not found then
    raise exception 'adaptive_activation_policy_missing';
  end if;

  return public.set_adaptive_activation(
    'preview',
    'iszihmmbgsfefawqmnwo',
    p_enabled,
    p_head_sha,
    p_reason
  );
end;
$$;

revoke all on function public.set_adaptive_staging_activation(boolean, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.set_adaptive_staging_activation(boolean, text, text)
  to service_role;

comment on table public.adaptive_activation_policies is
  'Environment-isolated adaptive activation authority. Preview and Production bindings are independent rows keyed by (policy_key, environment).';

comment on function public.set_adaptive_activation(text, text, boolean, text, text) is
  'Fail-closed adaptive activation bound to one environment row, Supabase project, exact graph identity and deployment SHA; service-role only.';

commit;

-- Restore the current automated Comprehensive fulfilment continuation after the interim
-- manual transition. This is a forward correction only: Essential remains on its existing manual
-- boundary, payment remains atomic/idempotent, and no legacy reviewer/engagement dependency is
-- introduced.
--
-- A REPORT_READY recovery claim is allowed only for an exact, still-verified Comprehensive
-- PDF/supporting-register package. The worker skips generation for that recovery and continues
-- through the existing release and secure-delivery chain.

create or replace function public.record_payment_transition(
  p_order_reference text,
  p_new_state text,
  p_source text,
  p_actor_reference text,
  p_amount_cents integer,
  p_currency text,
  p_provider_transaction_reference text,
  p_provider_event_reference text,
  p_provider_event_at timestamptz,
  p_safe_note text,
  p_verification_result text,
  p_idempotency_key text,
  p_technical_reference text,
  p_payload_sha256 text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_record public.payment_automation_records%rowtype;
  v_existing public.payment_transition_events%rowtype;
  v_verifier public.admin_profiles%rowtype;
  v_old_state text;
  v_allowed boolean := false;
  v_prior_valid_source_event boolean := false;
  v_event public.payment_transition_events%rowtype;
  v_job_id uuid;
  v_job_version integer;
  v_job_request_key text;
  v_product_code text;
  v_fulfilment_result text := 'not_requested';
begin
  if p_new_state not in (
       'PAYMENT_PENDING', 'PAYMENT_PROCESSING', 'PAID', 'PAYMENT_FAILED',
       'PAYMENT_REVIEW_REQUIRED', 'REFUNDED', 'CANCELLED'
     )
     or p_source not in ('manual_admin', 'stitch_webhook', 'system_recovery')
     or coalesce(pg_catalog.btrim(p_order_reference), '') = ''
     or coalesce(pg_catalog.btrim(p_idempotency_key), '') = ''
     or coalesce(pg_catalog.btrim(p_technical_reference), '') = ''
     or coalesce(pg_catalog.btrim(p_verification_result), '') = '' then
    raise exception 'payment_transition_invalid_input';
  end if;

  -- Lock/read the order before any insert.  This makes the amount/currency and source checks part
  -- of the same transaction boundary as the transition while keeping duplicate calls harmless.
  select * into v_order
  from public.orders
  where order_reference = p_order_reference
  for update;
  if not found then raise exception 'payment_order_not_found'; end if;

  if p_new_state = 'PAID' then
    if p_amount_cents is distinct from v_order.amount_cents
       or pg_catalog.upper(coalesce(p_currency, '')) <> pg_catalog.upper(coalesce(v_order.currency, '')) then
      raise exception 'payment_paid_amount_or_currency_mismatch';
    end if;

    if p_source = 'manual_admin' then
      if p_verification_result <> 'authorised_manual_confirmation'
         or p_actor_reference is null
         or p_actor_reference !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'payment_manual_verification_invalid';
      end if;
      select * into v_verifier
      from public.admin_profiles
      where id = p_actor_reference::uuid
        and status = 'active';
      if not found or v_verifier.role not in ('platform_admin', 'finance_admin') then
        raise exception 'payment_manual_verifier_invalid';
      end if;
    elsif p_source = 'stitch_webhook' then
      if p_verification_result <> 'svix_signature_valid'
         or coalesce(pg_catalog.btrim(p_provider_transaction_reference), '') = ''
         or coalesce(pg_catalog.btrim(p_provider_event_reference), '') = ''
         or p_provider_event_at is null then
        raise exception 'payment_stitch_verification_invalid';
      end if;
    elsif p_source = 'system_recovery' then
      if p_verification_result <> 'system_recovery_reconciled' then
        raise exception 'payment_system_recovery_verification_invalid';
      end if;
      select exists (
        select 1
        from public.payment_transition_events prior_event
        where prior_event.order_id = v_order.id
          and prior_event.new_state = 'PAID'
          and prior_event.processing_result = 'applied'
          and (
            (
              prior_event.source = 'manual_admin'
              and prior_event.verification_result = 'authorised_manual_confirmation'
              and prior_event.actor_reference ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
              and exists (
                select 1 from public.admin_profiles verifier
                where verifier.id = prior_event.actor_reference::uuid
                  and verifier.status = 'active'
                  and verifier.role in ('platform_admin', 'finance_admin')
              )
            )
            or (
              prior_event.source = 'stitch_webhook'
              and prior_event.verification_result = 'svix_signature_valid'
              and coalesce(pg_catalog.btrim(prior_event.provider_transaction_reference), '') <> ''
              and coalesce(pg_catalog.btrim(prior_event.provider_event_reference), '') <> ''
              and prior_event.provider_event_at is not null
            )
          )
      ) into v_prior_valid_source_event;
      if not v_prior_valid_source_event then
        raise exception 'payment_system_recovery_unverified';
      end if;
    end if;
  end if;

  select * into v_existing
  from public.payment_transition_events
  where idempotency_key = p_idempotency_key;
  if found then
    return pg_catalog.jsonb_build_object(
      'applied', false,
      'duplicate', true,
      'state', v_existing.new_state,
      'event_id', v_existing.id,
      'fulfilment_attempt_id', null
    );
  end if;

  insert into public.payment_automation_records(
    order_id, state, expected_amount_cents, currency
  ) values (
    v_order.id,
    case
      when v_order.status::text = 'payment_received' then 'PAID'
      when v_order.status::text in ('cancelled', 'expired') then 'CANCELLED'
      else 'PAYMENT_PENDING'
    end,
    v_order.amount_cents,
    v_order.currency
  )
  on conflict(order_id) do nothing;

  select * into v_record
  from public.payment_automation_records
  where order_id = v_order.id
  for update;
  v_old_state := v_record.state;

  if v_old_state = p_new_state then
    select * into v_existing
    from public.payment_transition_events
    where order_id = v_order.id and new_state = p_new_state
    order by created_at desc
    limit 1;
    return pg_catalog.jsonb_build_object(
      'applied', false,
      'duplicate', true,
      'state', p_new_state,
      'event_id', v_existing.id,
      'fulfilment_attempt_id', null
    );
  elsif v_old_state = 'PAYMENT_PENDING'
        and p_new_state in (
          'PAYMENT_PROCESSING', 'PAID', 'PAYMENT_FAILED',
          'PAYMENT_REVIEW_REQUIRED', 'CANCELLED'
        ) then
    v_allowed := true;
  elsif v_old_state = 'PAYMENT_PROCESSING'
        and p_new_state in (
          'PAID', 'PAYMENT_FAILED', 'PAYMENT_REVIEW_REQUIRED', 'CANCELLED'
        ) then
    v_allowed := true;
  elsif v_old_state = 'PAYMENT_FAILED'
        and p_new_state in (
          'PAYMENT_PROCESSING', 'PAYMENT_REVIEW_REQUIRED', 'CANCELLED'
        ) then
    v_allowed := true;
  elsif v_old_state = 'PAYMENT_REVIEW_REQUIRED'
        and p_new_state in (
          'PAYMENT_PROCESSING', 'PAID', 'PAYMENT_FAILED', 'REFUNDED', 'CANCELLED'
        ) then
    v_allowed := true;
  elsif v_old_state = 'PAID'
        and p_new_state in ('PAYMENT_REVIEW_REQUIRED', 'REFUNDED') then
    v_allowed := true;
  end if;
  if not v_allowed then
    raise exception 'payment_transition_not_allowed:%->%', v_old_state, p_new_state;
  end if;

  insert into public.payment_transition_events(
    order_id, order_reference, old_state, new_state, source, actor_reference,
    amount_cents, currency, provider_transaction_reference, provider_event_reference,
    provider_event_at, safe_note, verification_result, idempotency_key,
    technical_reference, payload_sha256
  ) values (
    v_order.id, v_order.order_reference, v_old_state, p_new_state, p_source,
    pg_catalog.left(p_actor_reference, 200), p_amount_cents, pg_catalog.upper(p_currency),
    pg_catalog.left(p_provider_transaction_reference, 300), pg_catalog.left(p_provider_event_reference, 300),
    p_provider_event_at, pg_catalog.left(p_safe_note, 500), pg_catalog.left(p_verification_result, 100),
    pg_catalog.left(p_idempotency_key, 300), pg_catalog.left(p_technical_reference, 200), p_payload_sha256
  ) returning * into v_event;

  update public.payment_automation_records
  set state = p_new_state,
      received_amount_cents = p_amount_cents,
      currency = pg_catalog.upper(p_currency),
      confirmation_source = p_source,
      actor_reference = pg_catalog.left(p_actor_reference, 200),
      provider_transaction_reference = pg_catalog.left(p_provider_transaction_reference, 300),
      provider_event_reference = pg_catalog.left(p_provider_event_reference, 300),
      verification_result = pg_catalog.left(p_verification_result, 100),
      review_reason = case when p_new_state = 'PAYMENT_REVIEW_REQUIRED' then pg_catalog.left(p_safe_note, 500) else null end,
      last_event_at = coalesce(p_provider_event_at, pg_catalog.now()),
      updated_at = pg_catalog.now()
  where order_id = v_order.id;

  update public.orders
  set status = case
        when p_new_state = 'PAID' then 'payment_received'::public.order_status
        when p_new_state in ('CANCELLED', 'REFUNDED') then 'cancelled'::public.order_status
        else 'awaiting_payment'::public.order_status
      end,
      verified_at = case when p_new_state = 'PAID' then pg_catalog.now() else verified_at end,
      verified_by = case
        when p_new_state = 'PAID' and p_source = 'manual_admin' then p_actor_reference::uuid
        else verified_by
      end,
      updated_at = pg_catalog.now()
  where id = v_order.id;

  insert into public.order_events(
    order_id, event_type, previous_status, new_status, note, actor_admin_user_id, metadata_json
  ) values (
    v_order.id, 'payment_transition', v_order.status,
    case
      when p_new_state = 'PAID' then 'payment_received'::public.order_status
      when p_new_state in ('CANCELLED', 'REFUNDED') then 'cancelled'::public.order_status
      else 'awaiting_payment'::public.order_status
    end,
    pg_catalog.left(p_safe_note, 500),
    case when p_source = 'manual_admin' then p_actor_reference::uuid else null end,
    pg_catalog.jsonb_build_object(
      'payment_state', p_new_state, 'source', p_source,
      'verification_result', p_verification_result,
      'provider_event_reference', p_provider_event_reference,
      'technical_reference', p_technical_reference
    )
  );

  if p_new_state = 'PAID' then
    select product.product_code into v_product_code
    from public.products product
    where product.id = v_order.product_id;

    -- Comprehensive is the only product on this automated route. Essential retains its
    -- established manual fulfilment behaviour and therefore receives no generation attempt.
    if v_product_code = 'mk_validated_assessment' then
      v_job_request_key := 'payment_fulfilment:' || v_order.id::text || ':' || p_idempotency_key;
      begin
        select coalesce(pg_catalog.max(version_number), 0) + 1 into v_job_version
        from public.reports where order_id = v_order.id;

        insert into public.manual_report_generation_attempts(
          request_key, order_id, report_version, trigger_source, requested_by,
          status, retry_count, technical_reference, max_attempts
        ) values (
          v_job_request_key, v_order.id, v_job_version, 'payment_confirmed', null,
          'REPORT_QUEUED', 0, p_technical_reference, 5
        )
        on conflict (request_key) do nothing
        returning id into v_job_id;
      exception when unique_violation then
        v_job_id := null;
      end;

      if v_job_id is not null then
        v_fulfilment_result := 'QUEUED';
        insert into public.order_events(order_id, event_type, note, metadata_json)
        values (
          v_order.id, 'generation_requested', 'Verified payment queued Comprehensive fulfilment.',
          pg_catalog.jsonb_build_object(
            'attempt_id', v_job_id, 'source', 'payment_confirmed', 'technical_reference', p_technical_reference
          )
        );
      else
        v_fulfilment_result := 'ALREADY_ACTIVE';
      end if;
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'applied', true, 'duplicate', false, 'state', p_new_state,
    'event_id', v_event.id, 'order_id', v_order.id,
    'fulfilment', v_fulfilment_result, 'fulfilment_attempt_id', v_job_id
  );
exception when unique_violation then
  select * into v_existing
  from public.payment_transition_events
  where idempotency_key = p_idempotency_key
     or (
       provider_event_reference is not null
       and provider_event_reference = p_provider_event_reference
       and source = p_source
     )
  order by created_at
  limit 1;
  if found then
    return pg_catalog.jsonb_build_object(
      'applied', false, 'duplicate', true, 'state', v_existing.new_state,
      'event_id', v_existing.id, 'fulfilment_attempt_id', null
    );
  end if;
  raise;
end;
$$;

create or replace function public.claim_exact_fulfilment_job(
  p_attempt_id uuid,
  p_lease_owner text,
  p_lease_seconds integer default 300
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job public.manual_report_generation_attempts%rowtype;
  v_order public.orders%rowtype;
  v_payment public.payment_automation_records%rowtype;
  v_product public.products%rowtype;
  v_report public.reports%rowtype;
  v_register public.report_artifacts%rowtype;
  v_verified_register_count integer;
  v_generation_event_count integer;
begin
  perform public.rc1_require_operation_open('worker');
  if p_attempt_id is null
     or coalesce(pg_catalog.btrim(p_lease_owner), '') = '' then
    raise exception 'fulfilment_exact_claim_input_invalid';
  end if;
  if p_lease_seconds is null
     or p_lease_seconds < 30
     or p_lease_seconds > 3600 then
    raise exception 'fulfilment_lease_seconds_out_of_range';
  end if;

  select * into v_job
  from public.manual_report_generation_attempts
  where id = p_attempt_id
  for update;
  if not found then raise exception 'fulfilment_exact_attempt_not_found'; end if;

  select * into v_order
  from public.orders
  where id = v_job.order_id
  for share;
  select * into v_payment
  from public.payment_automation_records
  where order_id = v_job.order_id
  for share;
  if not found
     or v_order.id is distinct from v_job.order_id
     or v_order.status::text <> 'payment_received'
     or v_payment.state <> 'PAID' then
    raise exception 'fulfilment_exact_attempt_order_ineligible';
  end if;

  if v_job.status = 'DELIVERY_QUEUED'
     and v_job.automatic_delivery_authorization_id is not null then
    return pg_catalog.jsonb_build_object(
      'id', v_job.id,
      'order_id', v_job.order_id,
      'already_complete', true,
      'automatic_delivery_authorization_id',
        v_job.automatic_delivery_authorization_id
    );
  end if;

  if v_job.status = 'REPORT_READY' then
    -- A verified package may have committed before its immediate dispatch completed. Claim it
    -- only for Comprehensive, only when the exact PDF/register pair is still intact, and leave
    -- REPORT_READY in place so the existing release gate remains the authoritative transition.
    if (
      v_job.next_attempt_at is not null
      and v_job.next_attempt_at > pg_catalog.now()
    )
    or (
      v_job.lease_expires_at is not null
      and v_job.lease_expires_at > pg_catalog.now()
    ) then
      return null;
    end if;

    select * into v_product
    from public.products
    where id = v_order.product_id
    for share;
    select * into v_report
    from public.reports
    where id = v_job.output_report_id
    for share;
    select count(*) into v_verified_register_count
    from public.report_artifacts
    where report_id = v_job.output_report_id
      and engagement_id is null
      and artefact_type = 'supporting_register'
      and artifact_version = v_job.report_version
      and storage_status = 'VERIFIED'
      and release_state in ('verified', 'released');

    select count(*) into v_generation_event_count
    from public.report_events
    where report_id = v_job.output_report_id
      and event_type in ('generated', 'regenerated')
      and metadata_json->>'attempt_id' = v_job.id::text
      and metadata_json->>'storage_status' = 'VERIFIED';

    if v_verified_register_count = 1 then
      select * into v_register
      from public.report_artifacts
      where report_id = v_job.output_report_id
        and engagement_id is null
        and artefact_type = 'supporting_register'
        and artifact_version = v_job.report_version
        and storage_status = 'VERIFIED'
        and release_state in ('verified', 'released');
    end if;

    if v_product.product_code is distinct from 'mk_validated_assessment'
       or v_report.id is null
       or v_report.order_id is distinct from v_job.order_id
       or v_report.report_type is distinct from 'mk_validated'
       or v_report.version_number is distinct from v_job.report_version
       or v_report.status is distinct from 'generated'
       or v_report.storage_status is distinct from 'VERIFIED'
       or v_report.storage_verified_at is null
       or coalesce(v_report.file_size_bytes, 0) <= 0
       or v_report.mime_type is distinct from 'application/pdf'
       or coalesce(pg_catalog.btrim(v_report.storage_bucket), '') = ''
       or coalesce(pg_catalog.btrim(v_report.storage_path), '') = ''
       or coalesce(v_report.checksum, '') !~ '^[0-9a-f]{64}$'
       or v_verified_register_count <> 1
       or v_generation_event_count < 1
       or coalesce(v_register.checksum_sha256, '') !~ '^[0-9a-f]{64}$'
       or coalesce(pg_catalog.btrim(v_register.storage_bucket), '') = ''
       or coalesce(pg_catalog.btrim(v_register.storage_path), '') = ''
       or coalesce(v_register.file_size_bytes, 0) <= 0
       or v_register.mime_type is distinct from 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' then
      return null;
    end if;

    -- The first real Preview package was generated before the automated release evidence fields
    -- were persisted. Recover only that narrow, otherwise fully verified state. The values below
    -- describe package/storage integrity and retain the existing assurance boundary; they are not
    -- a new commercial-quality or operating-effectiveness claim.
    if v_job.evidence_checksum is null and v_job.final_validation_json is null then
      update public.manual_report_generation_attempts
      set evidence_checksum = v_report.checksum,
          final_validation_json = pg_catalog.jsonb_build_object(
            'validation_mode', 'verified_comprehensive_package_recovery',
            'contract_version', 'comprehensive-product-v1.1',
            'report_checksum', v_report.checksum,
            'supporting_register_checksum', v_register.checksum_sha256,
            'artifact_version', v_job.report_version,
            'review_required', false,
            'independent_validation_performed', false,
            'operating_effectiveness_tested', false,
            'assurance_opinion_provided', false,
            'provider_generation_reused', true
          ),
          updated_at = pg_catalog.now()
      where id = v_job.id
      returning * into v_job;
    elsif coalesce(v_job.evidence_checksum, '') !~ '^[0-9a-f]{64}$'
       or v_job.evidence_checksum is distinct from v_report.checksum
       or v_job.final_validation_json is null
       or pg_catalog.jsonb_typeof(v_job.final_validation_json) <> 'object'
       or v_job.final_validation_json->>'report_checksum' is distinct from v_report.checksum
       or v_job.final_validation_json->>'supporting_register_checksum' is distinct from v_register.checksum_sha256
       or v_job.final_validation_json->>'artifact_version' is distinct from v_job.report_version::text then
      return null;
    end if;

    update public.manual_report_generation_attempts
    set lease_owner = p_lease_owner,
        lease_expires_at =
          pg_catalog.now() + pg_catalog.make_interval(secs => p_lease_seconds),
        heartbeat_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where id = v_job.id
    returning * into v_job;

    insert into public.audit_logs(
      actor_type, entity_table, entity_id, action, after_json
    ) values (
      'system',
      'manual_report_generation_attempts',
      v_job.id,
      'verified_comprehensive_fulfilment_recovered',
      pg_catalog.jsonb_build_object(
        'attempt_id', v_job.id,
        'order_id', v_job.order_id,
        'report_id', v_job.output_report_id,
        'lease_owner', p_lease_owner,
        'lease_expires_at', v_job.lease_expires_at,
        'provider_generation_reused', true,
        'recovered_validation_evidence', true
      )
    );

    return pg_catalog.to_jsonb(v_job)
      || pg_catalog.jsonb_build_object(
        'already_generated', true,
        'output_report_id', v_job.output_report_id
      );
  end if;

  if v_job.status not in ('REPORT_QUEUED', 'RETRY_SCHEDULED')
     or (
       v_job.next_attempt_at is not null
       and v_job.next_attempt_at > pg_catalog.now()
     )
     or (
       v_job.lease_expires_at is not null
       and v_job.lease_expires_at > pg_catalog.now()
     ) then
    return null;
  end if;

  update public.manual_report_generation_attempts
  set status = 'REPORT_QUEUED',
      lease_owner = p_lease_owner,
      lease_expires_at =
        pg_catalog.now() + pg_catalog.make_interval(secs => p_lease_seconds),
      heartbeat_at = pg_catalog.now(),
      started_at = coalesce(started_at, pg_catalog.now()),
      next_attempt_at = null,
      updated_at = pg_catalog.now()
  where id = v_job.id
  returning * into v_job;

  insert into public.audit_logs(
    actor_type, entity_table, entity_id, action, after_json
  ) values (
    'system',
    'manual_report_generation_attempts',
    v_job.id,
    'exact_fulfilment_job_claimed',
    pg_catalog.jsonb_build_object(
      'attempt_id', v_job.id,
      'order_id', v_job.order_id,
      'lease_owner', p_lease_owner,
      'lease_expires_at', v_job.lease_expires_at
    )
  );

  return pg_catalog.to_jsonb(v_job);
end;
$$;

revoke all on function public.claim_exact_fulfilment_job(uuid, text, integer) from public, anon, authenticated, service_role;
grant execute on function public.claim_exact_fulfilment_job(uuid, text, integer) to service_role;

-- Bounded current-path correction for the Preview V2 closure.
--
-- The active delivery worker receives the authoritative mode from sendEmail(), but the original
-- three-argument finalizer had no mode parameters and therefore left the durable ledger at its
-- default (`disabled`) even after a test/live provider acceptance.  Keep the original signature
-- intact for historical callers and add an explicit overload for the active worker.  The wrapper
-- updates the linked rows only after validating the same lease/state boundary, then delegates to
-- the existing finalizer in the same transaction.  This preserves its idempotency and provider
-- reconciliation semantics without inferring mode from recipient or environment later.

create or replace function public.finalize_delivery(
  p_authorization_id uuid,
  p_lease_token uuid,
  p_provider_message_id text,
  p_provider_mode text,
  p_test_delivery boolean
) returns jsonb
language plpgsql
security definer
set search_path = 'public', 'pg_temp'
as $$
declare
  v_authorization public.report_delivery_authorizations%rowtype;
  v_mode text := lower(pg_catalog.btrim(coalesce(p_provider_mode, '')));
begin
  if v_mode not in ('disabled', 'test', 'live') then
    raise exception 'delivery_provider_mode_invalid';
  end if;
  if p_test_delivery is distinct from (v_mode = 'test') then
    raise exception 'delivery_test_mode_mismatch';
  end if;
  if coalesce(pg_catalog.btrim(p_provider_message_id), '') = '' then
    raise exception 'delivery_provider_message_id_required';
  end if;

  select * into v_authorization
  from public.report_delivery_authorizations
  where id = p_authorization_id
  for update;
  if not found then
    raise exception 'delivery_authorization_not_found';
  end if;
  if v_authorization.status <> 'dispatching'
     or v_authorization.lease_token <> p_lease_token then
    raise exception 'delivery_lease_invalid';
  end if;

  update public.email_events
  set provider_mode = v_mode,
      updated_at = pg_catalog.now()
  where id = v_authorization.email_event_id;
  if not found then
    raise exception 'delivery_email_event_not_found';
  end if;

  update public.report_delivery_authorizations
  set test_delivery = (v_mode = 'test'),
      updated_at = pg_catalog.now()
  where id = v_authorization.id;

  return public.finalize_delivery(
    p_authorization_id,
    p_lease_token,
    p_provider_message_id
  );
end;
$$;

revoke all on function public.finalize_delivery(uuid, uuid, text, text, boolean) from public, anon, authenticated;
grant execute on function public.finalize_delivery(uuid, uuid, text, text, boolean) to service_role;

-- Correct Production API-failure classification and environment attribution.
--
-- Legacy production_monitor_events rows are intentionally left with environment NULL. They remain
-- available for audit/history but are excluded from the corrected Production API failure metric
-- because the original schema did not preserve enough evidence to distinguish Preview from
-- Production reliably.

begin;

alter table public.production_monitor_events
  add column if not exists environment text;

alter table public.production_monitor_events
  drop constraint if exists production_monitor_events_environment_check;

alter table public.production_monitor_events
  add constraint production_monitor_events_environment_check
  check (environment is null or environment in ('preview', 'production'));

create index if not exists production_monitor_events_environment_occurred_idx
  on public.production_monitor_events(environment, occurred_at desc);

comment on column public.production_monitor_events.environment is
  'Runtime environment recorded at event creation. NULL denotes legacy events created before environment attribution was introduced.';

commit;

-- Two bounded forward corrections for the Comprehensive current path.
--
-- 1. FAIL CLOSED ON A DISCARDED MANUSCRIPT.
--    The first real Preview Comprehensive package reached REPORT_READY, release and delivery with
--    manual_report_generation_attempts.final_narrative_json null: the Comprehensive branch rendered
--    the customer PDF from an in-memory manuscript and never crossed the provenance boundary, which
--    was only ever wired for Essential. The accepted narrative therefore stopped existing when the
--    request ended, and a provider-free revision of a released report became impossible.
--
-- 2. A NAMED, SINGLE-PURPOSE RECOVERY-REVISION SEAM.
--
-- Nothing here rewrites history: V1 keeps its row, checksum, storage object, delivery ledger and
-- token record, and no earlier migration is modified.

create or replace function public.guard_comprehensive_manuscript_provenance()
returns trigger
language plpgsql
security definer
set search_path = 'public', 'pg_temp'
as $$
declare
  v_is_comprehensive boolean;
  v_validation_mode text;
begin
  if new.status is distinct from 'REPORT_READY' then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.status = 'REPORT_READY' then
    return new;
  end if;

  select exists (
    select 1
    from public.orders o
    join public.products p on p.id = o.product_id
    where o.id = new.order_id
      and p.product_code = 'mk_validated_assessment'
  ) into v_is_comprehensive;
  if not coalesce(v_is_comprehensive, false) then
    return new;
  end if;

  v_validation_mode := new.final_validation_json->>'validation_mode';
  if v_validation_mode = 'legacy_pdf_native_recovery_revision' then
    if coalesce(new.final_validation_json->>'source_report_checksum', '') !~ '^[0-9a-f]{64}$'
       or coalesce(new.final_validation_json->>'report_checksum', '') !~ '^[0-9a-f]{64}$'
       or coalesce((new.final_validation_json->>'provider_generation_reused')::boolean, false) is not true then
      raise exception 'comprehensive_recovery_revision_provenance_invalid';
    end if;
    return new;
  end if;

  if new.final_narrative_json is null
     or new.final_validation_json is null
     or coalesce(new.evidence_checksum, '') !~ '^[0-9a-f]{64}$'
     or coalesce(pg_catalog.btrim(new.resolved_model), '') = ''
     or new.narrative_prepared_at is null then
    raise exception 'comprehensive_manuscript_provenance_missing';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_comprehensive_manuscript_provenance
  on public.manual_report_generation_attempts;
create trigger trg_guard_comprehensive_manuscript_provenance
  before insert or update on public.manual_report_generation_attempts
  for each row execute function public.guard_comprehensive_manuscript_provenance();

create or replace function public.supersede_prior_version_report_access(
  p_current_report_id uuid,
  p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = 'public', 'pg_temp'
as $$
declare
  v_current public.reports%rowtype;
  v_prior public.reports%rowtype;
  v_note text := pg_catalog.btrim(coalesce(p_reason, ''));
  v_revoked jsonb;
begin
  perform public.rc1_require_operation_open('worker');
  if pg_catalog.length(v_note) < 5 then raise exception 'access_token_reason_too_short'; end if;

  select * into v_current from public.reports where id = p_current_report_id;
  if not found or v_current.status <> 'released' then
    raise exception 'supersede_access_current_report_not_released';
  end if;
  if v_current.supersedes_report_id is null then
    raise exception 'supersede_access_no_prior_version';
  end if;

  select * into v_prior from public.reports where id = v_current.supersedes_report_id for update;
  if not found or v_prior.status <> 'superseded' then
    raise exception 'supersede_access_prior_version_still_live';
  end if;

  with revoked as (
    update public.customer_report_access_tokens
    set revoked_at = pg_catalog.now(),
        revoked_reason = v_note,
        updated_at = pg_catalog.now()
    where report_id = v_prior.id and revoked_at is null
    returning id, purpose, access_count
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(revoked)), '[]'::jsonb) into v_revoked from revoked;

  insert into public.report_events (report_id, event_type, actor_user_id, note, metadata_json)
  values (
    v_prior.id, 'access_revoked', null, v_note,
    pg_catalog.jsonb_build_object(
      'superseded_by_report_id', v_current.id,
      'superseded_by_reference', v_current.report_reference,
      'revoked_tokens', v_revoked
    )
  );

  return pg_catalog.jsonb_build_object(
    'prior_report_id', v_prior.id,
    'prior_report_reference', v_prior.report_reference,
    'current_report_id', v_current.id,
    'revoked_tokens', v_revoked
  );
end;
$$;

revoke all on function public.supersede_prior_version_report_access(uuid, text) from public, anon, authenticated;
grant execute on function public.supersede_prior_version_report_access(uuid, text) to service_role;

-- Correct the recovery seam so it enters the existing automatic quality release rather than
-- pre-empting it. 20260904030000 is not edited; only the seam is redefined forward.

create or replace function public.create_comprehensive_recovery_revision(
  p_source_report_id uuid,
  p_source_checksum text,
  p_storage_path text,
  p_file_name text,
  p_file_size_bytes bigint,
  p_checksum text,
  p_register_storage_path text,
  p_register_file_name text,
  p_register_file_size_bytes bigint,
  p_register_checksum text,
  p_recovery_method text,
  p_authorised_copy_change jsonb,
  p_lease_owner text default 'comprehensive-recovery-revision',
  p_lease_seconds integer default 300
) returns jsonb
language plpgsql
security definer
set search_path = 'public', 'pg_temp'
as $$
declare
  v_source public.reports%rowtype;
  v_order public.orders%rowtype;
  v_product public.products%rowtype;
  v_assessment public.assessments%rowtype;
  v_source_register public.report_artifacts%rowtype;
  v_report public.reports%rowtype;
  v_artifact public.report_artifacts%rowtype;
  v_attempt public.manual_report_generation_attempts%rowtype;
  v_version integer;
  v_reference text;
  v_technical_reference text := pg_catalog.gen_random_uuid()::text;
  v_validation jsonb;
  v_release jsonb;
  v_lease_owner text := coalesce(pg_catalog.btrim(p_lease_owner), '');
begin
  perform public.rc1_require_operation_open('worker');
  if v_lease_owner = '' then raise exception 'comprehensive_recovery_lease_owner_required'; end if;
  if p_lease_seconds is null or p_lease_seconds < 30 or p_lease_seconds > 3600 then
    raise exception 'comprehensive_recovery_lease_seconds_out_of_range';
  end if;

  select * into v_source from public.reports where id = p_source_report_id for update;
  if not found then raise exception 'comprehensive_recovery_source_missing'; end if;
  if v_source.status <> 'released'
     or v_source.storage_status <> 'VERIFIED'
     or v_source.checksum is distinct from p_source_checksum then
    raise exception 'comprehensive_recovery_source_not_released_as_certified';
  end if;

  select * into v_order from public.orders where id = v_source.order_id for share;
  select * into v_product from public.products where id = v_order.product_id for share;
  if v_product.product_code is distinct from 'mk_validated_assessment' then
    raise exception 'comprehensive_recovery_product_not_comprehensive';
  end if;
  select * into v_assessment from public.assessments where id = v_source.assessment_id for share;

  select * into v_source_register from public.report_artifacts
  where report_id = v_source.id
    and artefact_type = 'supporting_register'
    and engagement_id is null
    and storage_status = 'VERIFIED'
  order by artifact_version desc limit 1;
  if not found then raise exception 'comprehensive_recovery_source_register_missing'; end if;

  if coalesce(p_file_size_bytes, 0) <= 0
     or p_checksum !~ '^[0-9a-f]{64}$'
     or p_checksum = p_source_checksum
     or coalesce(pg_catalog.btrim(p_storage_path), '') = ''
     or p_file_name not like '%.pdf'
     or coalesce(p_register_file_size_bytes, 0) <= 0
     or p_register_checksum !~ '^[0-9a-f]{64}$'
     or coalesce(pg_catalog.btrim(p_register_storage_path), '') = ''
     or p_register_file_name not like '%.xlsx'
     or coalesce(pg_catalog.btrim(p_recovery_method), '') = ''
     or p_authorised_copy_change is null then
    raise exception 'comprehensive_recovery_input_invalid';
  end if;

  if p_register_checksum is distinct from v_source_register.checksum_sha256
     or p_register_file_size_bytes is distinct from v_source_register.file_size_bytes then
    raise exception 'comprehensive_recovery_register_bytes_changed';
  end if;

  v_version := v_source.version_number + 1;
  v_reference := 'RPT-' || v_assessment.assessment_reference || '-V' || v_version;
  if position('/' || v_order.id::text || '/v' || v_version::text || '/' in p_storage_path) = 0
     or position('/' || v_order.id::text || '/v' || v_version::text || '/' in p_register_storage_path) = 0 then
    raise exception 'comprehensive_recovery_storage_binding_invalid';
  end if;
  if exists (select 1 from public.reports where report_reference = v_reference) then
    raise exception 'comprehensive_recovery_revision_already_exists';
  end if;

  v_validation := pg_catalog.jsonb_build_object(
    'validation_mode', 'legacy_pdf_native_recovery_revision',
    'contract_version', 'comprehensive-product-v1.1',
    'recovery_method', p_recovery_method,
    'source_report_id', v_source.id,
    'source_report_reference', v_source.report_reference,
    'source_report_checksum', p_source_checksum,
    'report_checksum', p_checksum,
    'supporting_register_checksum', p_register_checksum,
    'supporting_register_bytes_reused_unchanged', true,
    'artifact_version', v_version,
    'authorised_copy_change', p_authorised_copy_change,
    'provider_generation_reused', true,
    'provider_calls', 0,
    'canonical_manuscript_recovered', false,
    'review_required', false,
    'independent_validation_performed', false,
    'operating_effectiveness_tested', false,
    'assurance_opinion_provided', false
  );

  update public.reports set status = 'superseded', updated_at = pg_catalog.now()
  where id = v_source.id;

  insert into public.reports (
    assessment_id, organisation_id, order_id, score_run_id, template_id, report_type, status,
    report_reference, version_number, storage_bucket, storage_path, checksum, file_name, mime_type,
    file_size_bytes, storage_status, storage_verified_at, generated_by, generated_at,
    supersedes_report_id
  ) values (
    v_source.assessment_id, v_source.organisation_id, v_source.order_id, v_source.score_run_id,
    v_source.template_id, v_source.report_type, 'generated',
    v_reference, v_version, v_source.storage_bucket, p_storage_path, p_checksum, p_file_name,
    'application/pdf', p_file_size_bytes, 'VERIFIED', pg_catalog.now(), v_source.generated_by,
    pg_catalog.now(), v_source.id
  ) returning * into v_report;

  insert into public.report_artifacts (
    report_id, artefact_type, storage_bucket, storage_path, checksum_sha256, file_name, mime_type,
    file_size_bytes, storage_status, storage_verified_at, engagement_id, artifact_version,
    release_state
  ) values (
    v_report.id, 'supporting_register', v_source_register.storage_bucket, p_register_storage_path,
    p_register_checksum, p_register_file_name,
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    p_register_file_size_bytes, 'VERIFIED', pg_catalog.now(), null, v_version,
    'verified'
  ) returning * into v_artifact;

  insert into public.manual_report_generation_attempts (
    request_key, order_id, assessment_id, report_version, trigger_source, requested_by, status,
    technical_reference, output_report_id, evidence_checksum, final_validation_json,
    narrative_prepared_at, lease_owner, lease_expires_at, heartbeat_at
  ) values (
    'comprehensive-recovery-revision-' || v_report.id::text, v_order.id, v_source.assessment_id,
    v_version, 'admin_regenerate', v_source.generated_by, 'REPORT_READY',
    v_technical_reference, v_report.id, p_checksum, v_validation,
    pg_catalog.now(), v_lease_owner,
    pg_catalog.now() + pg_catalog.make_interval(secs => p_lease_seconds), pg_catalog.now()
  ) returning * into v_attempt;

  perform pg_catalog.set_config('phase14.authoritative_transition', 'authenticated_rpc', true);

  insert into public.report_events (report_id, event_type, from_status, to_status, actor_user_id, note, metadata_json)
  values (
    v_report.id, 'regenerated', 'REPORT_GENERATING', 'REPORT_READY', v_source.generated_by,
    'Recovery revision produced from the released, checksum-verified previous version.',
    pg_catalog.jsonb_build_object(
      'attempt_id', v_attempt.id,
      'technical_reference', v_technical_reference,
      'retry_count', 0,
      'storage_status', 'VERIFIED',
      'file_size_bytes', p_file_size_bytes,
      'supporting_register_bytes', p_register_file_size_bytes,
      'recovery_method', p_recovery_method,
      'source_report_id', v_source.id,
      'provider_calls', 0
    )
  );
  insert into public.order_events (order_id, event_type, actor_admin_user_id, note, metadata_json)
  values (
    v_order.id, 'report_stored', v_source.generated_by,
    'Recovery revision stored and verified; previous version superseded and retained.',
    pg_catalog.jsonb_build_object(
      'attempt_id', v_attempt.id, 'report_id', v_report.id, 'storage_status', 'VERIFIED',
      'technical_reference', v_technical_reference, 'report_version', v_version,
      'superseded_report_id', v_source.id
    )
  );

  v_release := public.automatic_release_completed_fulfilment(v_attempt.id, v_report.id, v_lease_owner);
  if not coalesce((v_release->>'released')::boolean, false) then
    raise exception 'comprehensive_recovery_release_refused: %',
      coalesce(v_release->>'category', v_release->>'error_category', v_release::text);
  end if;
  if (v_release->>'delivery_authorization_id') is null then
    raise exception 'comprehensive_recovery_release_authorization_missing';
  end if;

  select * into v_report from public.reports where id = v_report.id;
  select * into v_artifact from public.report_artifacts where id = v_artifact.id;
  select * into v_attempt from public.manual_report_generation_attempts where id = v_attempt.id;
  if v_report.status <> 'released' or v_artifact.release_state <> 'released' then
    raise exception 'comprehensive_recovery_release_state_incomplete';
  end if;

  return pg_catalog.jsonb_build_object(
    'report', pg_catalog.to_jsonb(v_report),
    'supporting_register', pg_catalog.to_jsonb(v_artifact),
    'attempt', pg_catalog.to_jsonb(v_attempt),
    'superseded_report_id', v_source.id,
    'release', v_release,
    'delivery_authorization_id', v_release->>'delivery_authorization_id'
  );
end;
$$;

revoke all on function public.create_comprehensive_recovery_revision(
  uuid, text, text, text, bigint, text, text, text, bigint, text, text, jsonb, text, integer
) from public, anon, authenticated;
grant execute on function public.create_comprehensive_recovery_revision(
  uuid, text, text, text, bigint, text, text, text, bigint, text, text, jsonb, text, integer
) to service_role;

drop function if exists public.create_comprehensive_recovery_revision(
  uuid, text, text, text, bigint, text, text, text, bigint, text, text, jsonb
);

-- Frozen proof-run support.
--
-- This migration adds two additive contracts:
--   1. explicit synthetic-demonstration markers and an auditable, order-free
--      Comprehensive fixture-generation record;
--   2. safe Essential provider diagnostics and score explainability metadata.
--
-- The synthetic path is deliberately separate from commercial Comprehensive fulfilment. It has
-- no order, payment, invoice, engagement, email or customer-delivery transition, and its RPCs are
-- service-role-only. The application route still requires an authenticated platform administrator.

begin;

alter table public.assessments
  add column if not exists synthetic_demonstration boolean not null default false,
  add column if not exists synthetic_certification_ref text;

alter table public.reports
  add column if not exists synthetic_demonstration boolean not null default false,
  add column if not exists synthetic_certification_ref text;

alter table public.manual_report_generation_attempts
  add column if not exists failure_diagnostics_json jsonb not null default '{}'::jsonb;

alter table public.assessments
  drop constraint if exists assessments_synthetic_marker_check;
alter table public.assessments
  add constraint assessments_synthetic_marker_check
  check (
    (synthetic_demonstration = false and synthetic_certification_ref is null)
    or (synthetic_demonstration = true
      and synthetic_certification_ref ~ '^MK-SYN-[0-9]{8}-[A-Z0-9-]{1,40}$')
  );

alter table public.reports
  drop constraint if exists reports_synthetic_marker_check;
alter table public.reports
  add constraint reports_synthetic_marker_check
  check (
    (synthetic_demonstration = false and synthetic_certification_ref is null)
    or (synthetic_demonstration = true
      and synthetic_certification_ref ~ '^MK-SYN-[0-9]{8}-[A-Z0-9-]{1,40}$')
  );

create or replace function public.guard_synthetic_assessment_marker()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if new.synthetic_demonstration
     and coalesce(new.synthetic_certification_ref, '') !~ '^MK-SYN-[0-9]{8}-[A-Z0-9-]{1,40}$' then
    raise exception 'synthetic_assessment_marker_invalid';
  end if;
  if not new.synthetic_demonstration and new.synthetic_certification_ref is not null then
    raise exception 'synthetic_assessment_reference_without_marker';
  end if;
  if tg_op = 'UPDATE'
     and old.synthetic_demonstration
     and (not new.synthetic_demonstration
       or new.synthetic_certification_ref is distinct from old.synthetic_certification_ref) then
    raise exception 'synthetic_assessment_marker_immutable';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_synthetic_assessment_marker on public.assessments;
create trigger trg_guard_synthetic_assessment_marker
before insert or update of synthetic_demonstration, synthetic_certification_ref
on public.assessments
for each row execute function public.guard_synthetic_assessment_marker();

create or replace function public.guard_synthetic_report_marker()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_assessment public.assessments%rowtype;
begin
  select * into v_assessment
  from public.assessments
  where id = new.assessment_id;
  if not found then
    raise exception 'synthetic_report_assessment_missing';
  end if;

  if v_assessment.synthetic_demonstration then
    if new.order_id is not null then
      raise exception 'synthetic_report_order_binding_forbidden';
    end if;
    new.synthetic_demonstration := true;
    new.synthetic_certification_ref := v_assessment.synthetic_certification_ref;
  elsif new.synthetic_demonstration or new.synthetic_certification_ref is not null then
    raise exception 'ordinary_report_synthetic_marker_forbidden';
  end if;

  if new.synthetic_demonstration
     and coalesce(new.synthetic_certification_ref, '') !~ '^MK-SYN-[0-9]{8}-[A-Z0-9-]{1,40}$' then
    raise exception 'synthetic_report_marker_invalid';
  end if;
  if tg_op = 'UPDATE'
     and old.synthetic_demonstration
     and (not new.synthetic_demonstration
       or new.synthetic_certification_ref is distinct from old.synthetic_certification_ref) then
    raise exception 'synthetic_report_marker_immutable';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_synthetic_report_marker on public.reports;
create trigger trg_guard_synthetic_report_marker
before insert or update of assessment_id, order_id, synthetic_demonstration, synthetic_certification_ref
on public.reports
for each row execute function public.guard_synthetic_report_marker();

create index if not exists assessments_synthetic_demonstration_idx
  on public.assessments(synthetic_demonstration, synthetic_certification_ref);
create index if not exists reports_synthetic_demonstration_idx
  on public.reports(synthetic_demonstration, synthetic_certification_ref);

-- Completed score runs are immutable by contract. Explanatory scope/cap metadata therefore lives
-- in an additive companion row and is merged at read time; this migration never updates a locked
-- score run or rewrites a score, maturity, denominator, trace or cap event.
create table if not exists public.synthetic_score_explainability (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references public.assessments(id) on delete restrict,
  score_run_id uuid not null references public.score_runs(id) on delete restrict,
  synthetic_certification_ref text not null
    check (synthetic_certification_ref ~ '^MK-SYN-[0-9]{8}-[A-Z0-9-]{1,40}$'),
  limitation_reasons text[] not null default '{}'::text[],
  cap_effect text not null check (cap_effect in ('band_lowered', 'no_band_change', 'none')),
  source_contract text not null default 'adaptive-explainability-v1',
  created_at timestamptz not null default now(),
  unique (score_run_id),
  unique (assessment_id)
);

create index if not exists synthetic_score_explainability_assessment_idx
  on public.synthetic_score_explainability(assessment_id);
alter table public.synthetic_score_explainability enable row level security;
revoke all on table public.synthetic_score_explainability from public, anon, authenticated;
grant select, insert, update on table public.synthetic_score_explainability to service_role;

create table if not exists public.synthetic_report_generation_records (
  id uuid primary key default gen_random_uuid(),
  request_key text not null unique,
  technical_reference text not null unique,
  assessment_id uuid not null references public.assessments(id) on delete restrict,
  report_id uuid references public.reports(id) on delete set null,
  report_type public.report_type not null,
  report_version integer not null check (report_version > 0),
  synthetic_certification_ref text not null
    check (synthetic_certification_ref ~ '^MK-SYN-[0-9]{8}-[A-Z0-9-]{1,40}$'),
  route text not null check (route = 'comprehensive_synthetic_fixture'),
  status text not null check (status in ('generating', 'ready', 'failed')),
  requested_by uuid not null references public.admin_profiles(id) on delete restrict,
  engine_contract text not null,
  provider text,
  model text,
  provider_calls integer not null default 0 check (provider_calls between 0 and 3),
  report_checksum text check (report_checksum is null or report_checksum ~ '^[0-9a-f]{64}$'),
  storage_bucket text,
  storage_path text,
  file_name text,
  file_size_bytes bigint check (file_size_bytes is null or file_size_bytes > 0),
  error_category text,
  safe_error_message text,
  failure_diagnostics_json jsonb not null default '{}'::jsonb,
  metadata_json jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  unique (assessment_id, report_type, report_version)
);

create index if not exists synthetic_report_generation_records_assessment_idx
  on public.synthetic_report_generation_records(assessment_id, created_at desc);
create index if not exists synthetic_report_generation_records_status_idx
  on public.synthetic_report_generation_records(status, created_at desc);

alter table public.synthetic_report_generation_records enable row level security;
revoke all on table public.synthetic_report_generation_records from public, anon, authenticated;
grant select, insert, update on table public.synthetic_report_generation_records to service_role;

comment on table public.synthetic_report_generation_records is
  'Non-commercial owner-review Comprehensive fixture generations. Every row is explicitly synthetic and order-free.';
comment on column public.manual_report_generation_attempts.failure_diagnostics_json is
  'Bounded provider identity/accounting diagnostics only; raw prompts, response bodies and customer prose are prohibited.';

-- Synthetic Comprehensive claim. This is the only database entry point that can create a fixture
-- generation record. It never creates an order or engagement and rejects ordinary assessments.
create or replace function public.claim_synthetic_comprehensive_generation(
  p_assessment_reference text,
  p_requested_by uuid,
  p_request_key text,
  p_technical_reference text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_assessment public.assessments%rowtype;
  v_score public.score_runs%rowtype;
  v_profile public.admin_profiles%rowtype;
  v_existing public.synthetic_report_generation_records%rowtype;
  v_current public.reports%rowtype;
  v_record public.synthetic_report_generation_records%rowtype;
  v_version integer;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'synthetic_generation_service_role_required';
  end if;
  if coalesce(trim(p_assessment_reference), '') = ''
     or coalesce(trim(p_request_key), '') = ''
     or coalesce(trim(p_technical_reference), '') = '' then
    raise exception 'synthetic_generation_request_identity_required';
  end if;
  if length(p_request_key) > 240 or length(p_technical_reference) > 160 then
    raise exception 'synthetic_generation_request_identity_invalid';
  end if;

  select * into v_profile
  from public.admin_profiles
  where id = p_requested_by and status = 'active';
  if not found or v_profile.role <> 'platform_admin' then
    raise exception 'synthetic_generation_platform_admin_required';
  end if;

  select * into v_existing
  from public.synthetic_report_generation_records
  where request_key = p_request_key;
  if found then
    if v_existing.status = 'ready' and v_existing.report_id is not null then
      return jsonb_build_object('claimed', false, 'reason', 'idempotent_replay', 'record', to_jsonb(v_existing));
    end if;
    if v_existing.status = 'generating' then
      return jsonb_build_object('claimed', false, 'reason', 'already_active', 'record', to_jsonb(v_existing));
    end if;
    raise exception 'synthetic_generation_request_already_failed';
  end if;

  select * into v_assessment
  from public.assessments
  where assessment_reference = p_assessment_reference
  for update;
  if not found then raise exception 'synthetic_generation_assessment_not_found'; end if;
  if not v_assessment.synthetic_demonstration
     or coalesce(v_assessment.synthetic_certification_ref, '') = '' then
    raise exception 'synthetic_generation_marker_required';
  end if;
  if v_assessment.monitoring_synthetic then
    raise exception 'synthetic_generation_monitoring_fixture_forbidden';
  end if;
  if v_assessment.assessment_mode <> 'adaptive'
     or v_assessment.status not in ('scored','snapshot_available','report_requested','under_review','closed')
     or v_assessment.submitted_at is null
     or v_assessment.locked_at is null
     or v_assessment.current_score_run_id is null then
    raise exception 'synthetic_generation_assessment_incomplete';
  end if;

  select * into v_score
  from public.score_runs
  where id = v_assessment.current_score_run_id
    and assessment_id = v_assessment.id
    and status = 'completed'
    and locked_at is not null;
  if not found then raise exception 'synthetic_generation_score_not_locked'; end if;

  if exists (select 1 from public.orders where assessment_id = v_assessment.id) then
    raise exception 'synthetic_generation_order_binding_forbidden';
  end if;

  -- Never let a fixture overwrite or supersede a commercial Comprehensive report. This guard is
  -- intentionally independent of the synthetic marker trigger so a malformed row cannot weaken it.
  select * into v_current
  from public.reports
  where assessment_id = v_assessment.id
    and report_type = 'mk_validated'
    and status in ('generated','under_review','approved','released')
  order by version_number desc
  limit 1;
  if found and not v_current.synthetic_demonstration then
    raise exception 'synthetic_generation_commercial_report_exists';
  end if;

  select greatest(
    coalesce((select max(version_number) from public.reports where assessment_id = v_assessment.id and report_type = 'mk_validated'), 0),
    coalesce((select max(report_version) from public.synthetic_report_generation_records where assessment_id = v_assessment.id and report_type = 'mk_validated'), 0)
  ) + 1 into v_version;

  insert into public.synthetic_report_generation_records(
    request_key, technical_reference, assessment_id, report_type, report_version,
    synthetic_certification_ref, route, status, requested_by, engine_contract
  ) values (
    p_request_key, p_technical_reference, v_assessment.id, 'mk_validated', v_version,
    v_assessment.synthetic_certification_ref, 'comprehensive_synthetic_fixture', 'generating',
    p_requested_by, 'mk-comprehensive-manual-generation-v1'
  ) returning * into v_record;

  perform set_config('phase14.authoritative_transition', 'authenticated_rpc', true);
  insert into public.audit_logs(
    actor_type, actor_user_id, assessment_id, entity_table, entity_id, action, after_json
  ) values (
    'admin', p_requested_by, v_assessment.id, 'synthetic_report_generation_records', v_record.id,
    'synthetic_comprehensive_generation_requested',
    jsonb_build_object(
      'technical_reference', p_technical_reference,
      'request_key', p_request_key,
      'report_type', 'mk_validated',
      'report_version', v_version,
      'synthetic_certification_ref', v_assessment.synthetic_certification_ref,
      'order_id', null,
      'payment_created', false,
      'customer_delivery_authorised', false
    )
  );

  return jsonb_build_object('claimed', true, 'record', to_jsonb(v_record), 'score_run_id', v_score.id);
end;
$$;

-- Synthetic Comprehensive completion. It shares the normal PDF renderer at the application seam,
-- but uses a dedicated order-free finalisation boundary and never calls the commercial package RPC.
create or replace function public.complete_synthetic_comprehensive_generation(
  p_record_id uuid,
  p_template_id uuid,
  p_storage_bucket text,
  p_storage_path text,
  p_file_name text,
  p_mime_type text,
  p_file_size_bytes bigint,
  p_checksum text,
  p_provider_calls integer,
  p_provider text,
  p_model text,
  p_metadata jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_record public.synthetic_report_generation_records%rowtype;
  v_assessment public.assessments%rowtype;
  v_score public.score_runs%rowtype;
  v_template public.report_templates%rowtype;
  v_previous public.reports%rowtype;
  v_report public.reports%rowtype;
  v_reference text;
  v_expected_prefix text;
  v_expected_file_name text;
  v_expected_storage_path text;
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object' then coalesce(p_metadata, '{}'::jsonb) else '{}'::jsonb end;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then raise exception 'synthetic_generation_service_role_required'; end if;
  select * into v_record from public.synthetic_report_generation_records where id = p_record_id for update;
  if not found or v_record.status <> 'generating' then raise exception 'synthetic_generation_record_not_active'; end if;
  select * into v_assessment from public.assessments where id = v_record.assessment_id for update;
  if not found or not v_assessment.synthetic_demonstration
     or v_assessment.synthetic_certification_ref is distinct from v_record.synthetic_certification_ref
     or v_assessment.monitoring_synthetic then raise exception 'synthetic_generation_assessment_binding_invalid'; end if;
  if exists (select 1 from public.orders where assessment_id = v_assessment.id) then raise exception 'synthetic_generation_order_binding_forbidden'; end if;
  select * into v_score from public.score_runs where id = v_assessment.current_score_run_id
    and assessment_id = v_assessment.id and status = 'completed' and locked_at is not null;
  if not found then raise exception 'synthetic_generation_score_not_locked'; end if;
  select * into v_template from public.report_templates where id = p_template_id and report_type = 'mk_validated' and status = 'active';
  if not found then raise exception 'synthetic_generation_template_invalid'; end if;
  if v_record.report_type <> 'mk_validated' or coalesce(p_storage_bucket, '') <> 'generated-reports'
     or coalesce(p_storage_path, '') = '' or position('..' in p_storage_path) > 0
     or coalesce(p_file_name, '') !~ '^[A-Za-z0-9._-]+\.pdf$' or p_mime_type <> 'application/pdf'
     or coalesce(p_file_size_bytes, 0) <= 0 or coalesce(p_checksum, '') !~ '^[0-9a-f]{64}$'
     or p_provider_calls is null or p_provider_calls < 1 or p_provider_calls > 3
     or coalesce(trim(p_provider), '') = '' or length(p_provider) > 160
     or coalesce(trim(p_model), '') = '' or length(p_model) > 240 then raise exception 'synthetic_generation_output_integrity_invalid'; end if;

  v_reference := 'RPT-' || v_assessment.assessment_reference || '-COMP-V' || v_record.report_version::text;
  v_expected_file_name := regexp_replace(v_reference, '[^A-Za-z0-9._-]', '_', 'g') || '.pdf';
  v_expected_prefix := v_assessment.organisation_id::text || '/' || v_assessment.id::text || '/synthetic-comprehensive/v' || v_record.report_version::text || '/';
  v_expected_storage_path := v_expected_prefix || regexp_replace(v_reference, '[^A-Za-z0-9._-]', '_', 'g') || '-' || left(p_checksum, 16) || '.pdf';
  if p_file_name <> v_expected_file_name or p_storage_path <> v_expected_storage_path then raise exception 'synthetic_generation_storage_binding_invalid'; end if;

  select * into v_previous from public.reports where assessment_id = v_assessment.id and report_type = 'mk_validated'
    and synthetic_demonstration and status in ('generated','under_review','approved','released')
  order by version_number desc limit 1 for update;
  if v_previous.id is not null then update public.reports set status = 'superseded', updated_at = now() where id = v_previous.id; end if;

  insert into public.reports(
    assessment_id, organisation_id, order_id, score_run_id, template_id, report_type, status,
    report_reference, version_number, storage_bucket, storage_path, checksum, file_name, mime_type,
    file_size_bytes, storage_status, storage_verified_at, generated_by, generated_at,
    supersedes_report_id, synthetic_demonstration, synthetic_certification_ref
  ) values (
    v_assessment.id, v_assessment.organisation_id, null, v_score.id, v_template.id, 'mk_validated', 'generated',
    v_reference, v_record.report_version, p_storage_bucket, p_storage_path, p_checksum, p_file_name, p_mime_type,
    p_file_size_bytes, 'VERIFIED', now(), v_record.requested_by, now(), v_previous.id, true, v_record.synthetic_certification_ref
  ) returning * into v_report;

  perform set_config('phase14.authoritative_transition', 'authenticated_rpc', true);
  insert into public.report_events(report_id, event_type, from_status, to_status, actor_user_id, note, metadata_json)
  values (
    v_report.id, case when v_previous.id is null then 'generated' else 'regenerated' end,
    'REPORT_GENERATING', 'REPORT_READY', v_record.requested_by,
    'Synthetic Comprehensive demonstration PDF stored and integrity verified.',
    jsonb_build_object('synthetic_demonstration', true, 'synthetic_certification_ref', v_record.synthetic_certification_ref,
      'technical_reference', v_record.technical_reference, 'provider_calls', p_provider_calls,
      'order_id', null, 'customer_delivery_authorised', false)
  );
  insert into public.assessment_events(assessment_id, organisation_id, respondent_id, order_id, report_id, event_type, dedupe_key, metadata_json)
  values (
    v_assessment.id, v_assessment.organisation_id, v_assessment.primary_respondent_id, null, v_report.id, 'report_generated',
    'synthetic-assessment:' || v_assessment.id::text || ':report_generated:' || v_report.id::text,
    jsonb_build_object('report_reference', v_report.report_reference, 'report_type', 'mk_validated', 'version_number', v_report.version_number,
      'score_run_id', v_score.id, 'synthetic_demonstration', true, 'order_id', null)
  );
  update public.synthetic_report_generation_records
  set report_id = v_report.id, status = 'ready', provider = p_provider, model = p_model,
      provider_calls = p_provider_calls, report_checksum = p_checksum, storage_bucket = p_storage_bucket,
      storage_path = p_storage_path, file_name = p_file_name, file_size_bytes = p_file_size_bytes,
      metadata_json = v_metadata, completed_at = now(), updated_at = now()
  where id = v_record.id;
  insert into public.audit_logs(actor_type, actor_user_id, assessment_id, entity_table, entity_id, action, after_json)
  values (
    'admin', v_record.requested_by, v_assessment.id, 'reports', v_report.id, 'synthetic_comprehensive_generation_completed',
    jsonb_build_object('synthetic_demonstration', true, 'synthetic_certification_ref', v_record.synthetic_certification_ref,
      'report_reference', v_report.report_reference, 'report_version', v_report.version_number, 'checksum', p_checksum,
      'file_size_bytes', p_file_size_bytes, 'provider', p_provider, 'model', p_model, 'provider_calls', p_provider_calls,
      'generation_record_id', v_record.id, 'order_id', null, 'payment_created', false, 'customer_delivery_authorised', false)
  );
  return jsonb_build_object('ok', true, 'record_id', v_record.id, 'report', to_jsonb(v_report),
    'superseded_report_id', v_previous.id, 'provider_calls', p_provider_calls);
end;
$$;

create or replace function public.fail_synthetic_comprehensive_generation(
  p_record_id uuid,
  p_error_category text,
  p_safe_message text,
  p_failure_diagnostics jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_record public.synthetic_report_generation_records%rowtype;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then raise exception 'synthetic_generation_service_role_required'; end if;
  update public.synthetic_report_generation_records
  set status = 'failed', error_category = left(coalesce(p_error_category, 'generation_failed'), 100),
      safe_error_message = left(coalesce(p_safe_message, 'Synthetic report generation failed.'), 500),
      failure_diagnostics_json = case when jsonb_typeof(coalesce(p_failure_diagnostics, '{}'::jsonb)) = 'object' then coalesce(p_failure_diagnostics, '{}'::jsonb) else '{}'::jsonb end,
      completed_at = now(), updated_at = now()
  where id = p_record_id and status = 'generating'
  returning * into v_record;
  if not found then return jsonb_build_object('updated', false); end if;
  perform set_config('phase14.authoritative_transition', 'authenticated_rpc', true);
  insert into public.audit_logs(actor_type, actor_user_id, assessment_id, entity_table, entity_id, action, after_json)
  values ('admin', v_record.requested_by, v_record.assessment_id, 'synthetic_report_generation_records', v_record.id,
    'synthetic_comprehensive_generation_failed', jsonb_build_object('technical_reference', v_record.technical_reference,
      'error_category', v_record.error_category, 'safe_error_message', v_record.safe_error_message,
      'failure_diagnostics', v_record.failure_diagnostics_json));
  return jsonb_build_object('updated', true, 'record', to_jsonb(v_record));
end;
$$;

-- Safe identity/accounting diagnostics for the assessment-scoped Essential path.
create or replace function public.record_assessment_manual_report_generation_diagnostics(
  p_attempt_id uuid,
  p_requested_provider text,
  p_requested_model text,
  p_resolved_provider text,
  p_resolved_model text,
  p_generation_mode text,
  p_ai_usage jsonb default '{}'::jsonb,
  p_failure_diagnostics jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_attempt public.manual_report_generation_attempts%rowtype;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then raise exception 'v12_generation_service_role_required'; end if;
  if p_generation_mode is not null and p_generation_mode not in ('ai','ai_repair','deterministic_fallback') then raise exception 'v12_generation_mode_invalid'; end if;
  update public.manual_report_generation_attempts
  set requested_provider = left(nullif(trim(p_requested_provider), ''), 160),
      requested_model = left(nullif(trim(p_requested_model), ''), 240),
      resolved_provider = left(nullif(trim(p_resolved_provider), ''), 160),
      resolved_model = left(nullif(trim(p_resolved_model), ''), 240),
      generation_mode = p_generation_mode,
      ai_usage_json = case when jsonb_typeof(coalesce(p_ai_usage, '{}'::jsonb)) = 'object' then coalesce(p_ai_usage, '{}'::jsonb) else '{}'::jsonb end,
      failure_diagnostics_json = case when jsonb_typeof(coalesce(p_failure_diagnostics, '{}'::jsonb)) = 'object' then coalesce(p_failure_diagnostics, '{}'::jsonb) else '{}'::jsonb end,
      updated_at = now()
  where id = p_attempt_id and order_id is null
    and trigger_source in ('assessment_admin_generate','assessment_admin_retry','assessment_admin_regenerate')
  returning * into v_attempt;
  if not found then return jsonb_build_object('updated', false); end if;
  perform set_config('phase14.authoritative_transition', 'authenticated_rpc', true);
  insert into public.audit_logs(actor_type, actor_user_id, assessment_id, entity_table, entity_id, action, after_json)
  values ('admin', v_attempt.requested_by, v_attempt.assessment_id, 'manual_report_generation_attempts', v_attempt.id,
    'phase14_assessment_report_generation_diagnostics_recorded',
    jsonb_build_object('requested_provider', v_attempt.requested_provider, 'requested_model', v_attempt.requested_model,
      'resolved_provider', v_attempt.resolved_provider, 'resolved_model', v_attempt.resolved_model,
      'generation_mode', v_attempt.generation_mode, 'ai_usage', v_attempt.ai_usage_json,
      'failure_diagnostics', v_attempt.failure_diagnostics_json));
  return jsonb_build_object('updated', true, 'attempt_id', v_attempt.id);
end;
$$;

create or replace function public.fail_assessment_manual_report_generation(
  p_attempt_id uuid,
  p_error_category text,
  p_safe_message text,
  p_failure_diagnostics jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_attempt public.manual_report_generation_attempts%rowtype;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then raise exception 'v12_generation_service_role_required'; end if;
  update public.manual_report_generation_attempts
  set status = 'GENERATION_FAILED', completed_at = now(), updated_at = now(),
      error_category = left(coalesce(p_error_category, 'generation_failed'), 80),
      safe_operational_error = left(coalesce(p_safe_message, 'Report generation failed.'), 500),
      failure_diagnostics_json = case when jsonb_typeof(coalesce(p_failure_diagnostics, '{}'::jsonb)) = 'object' then coalesce(p_failure_diagnostics, '{}'::jsonb) else '{}'::jsonb end
  where id = p_attempt_id and order_id is null
    and trigger_source in ('assessment_admin_generate','assessment_admin_retry','assessment_admin_regenerate')
    and status in ('REPORT_QUEUED','REPORT_GENERATING')
  returning * into v_attempt;
  if not found then return jsonb_build_object('updated', false); end if;
  perform set_config('phase14.authoritative_transition', 'authenticated_rpc', true);
  insert into public.audit_logs(actor_type, actor_user_id, assessment_id, entity_table, entity_id, action, after_json)
  values ('admin', v_attempt.requested_by, v_attempt.assessment_id, 'manual_report_generation_attempts', v_attempt.id,
    'phase14_assessment_report_generation_failed',
    jsonb_build_object('technical_reference', v_attempt.technical_reference, 'error_category', v_attempt.error_category,
      'safe_operational_error', v_attempt.safe_operational_error, 'failure_diagnostics', v_attempt.failure_diagnostics_json));
  return jsonb_build_object('updated', true, 'attempt', to_jsonb(v_attempt));
end;
$$;

